// sketch.js
let theShader;

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
  theShader.setUniform("u_time", millis() / 1000.0);

  rect(0, 0, 0);
}

function windowResized() {
  resizeCanvas(1112, 834);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed() {
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}


// === Tab: vert ===
// shader.vert
let vert = `
attribute vec3 aPosition; 
attribute vec2 aTexCoord; 
varying vec2 vTexCoord; 

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

// === Tab: frag ===
// **REFERENCE**
// https://www.shadertoy.com/view/3s3GDn
let frag = `

#ifdef GL_ES
precision mediump float;
#endif

#define PI 3.1415926535

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
varying vec2 vTexCoord; // uv

mat2 rotate2d(float _angle) {
  return mat2(
    cos(_angle), - sin(_angle),
    sin(_angle), cos(_angle)
  );
}
float distanceFrom(vec2 pos) {
  vec2 pos_rot = pos * rotate2d(sin(0.9));
  return max(abs(pos.x), abs(pos.y)) * max(abs(pos_rot.x), abs(pos_rot.y));
}

void main() {
  vec2 pos = 0.5 - vTexCoord;
  pos.y /= u_resolution.x / u_resolution.y;

  // 座標変換
  pos.y *= pos.x - (sin(u_time * 1.0) / 2.0); // 横移動
  pos.x *= vTexCoord.x * (1.0 - vTexCoord.x) * pow(abs(sin(u_time * 2.0 + PI / 2.0)+0.5), 2.0); // 横拡張
  pos.y = pos.y + 
    sin(vTexCoord.x * 4.0 + u_time/4.0) / 8.0 + 
    sin(vTexCoord.x * (3000.0 - sin(u_time/2.0)*4.0)) / 10.0; // 縦拡張
  pos *= rotate2d(sin(u_time * 2.0)); // 画面回転

  // Glow
  float dist = 0.0001 / distanceFrom(pos); // Glow
  dist = pow(dist, 0.5); // Gamma

  // Coloring
  vec3 col = dist * vec3(0.6 + sin(u_time) / 2.5, 0.5, 0.9);

  gl_FragColor = vec4(col, 1.0);
}
`;

